 byId('resetStyle').addEventListener('click',()=>{config.positionEase='sine.inOut';config.positionBezier=[.22,1,.36,1];easeSelect.value=config.positionEase;byId('bezierControls').hidden=true;bezierInputs.forEach((input,i)=>input.value=config.positionBezier[i]);saveMovement()});
 easeSelect.onchange=()=>{config.positionEase=easeSelect.value;byId('bezierControls').hidden=config.positionEase!=='custom';saveMovement()};duration.addEventListener('change',saveMovement);byId('control-positionDuration').addEventListener('change',saveMovement);
 byId('previewPositionEase').onclick=()=>{const dot=byId('easePreviewDot'),width=dot.parentElement.clientWidth-32,css={none:'linear','sine.inOut':'cubic-bezier(.37,0,.63,1)','power2.out':'cubic-bezier(.215,.61,.355,1)','power3.inOut':'cubic-bezier(.645,.045,.355,1)',custom:'cubic-bezier('+config.positionBezier.join(',')+')'};dot.getAnimations().forEach(a=>a.cancel());dot.animate([{transform:'translateX(0)'},{transform:'translateX('+width+'px)'}],{duration:config.positionEase==='direct'?0:config.positionDuration*1000,easing:css[config.positionEase]||'linear',fill:'forwards'});};

